int process_ticket(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void **p, void *end) {
    int ret = -EINVAL;
    uint32_t ticket_type, version;
    struct ceph_auth_ticket_handler *handler;
    void *ticket_data;
    size_t ticket_len;
    struct ceph_crypto_key new_key = {};
    struct ceph_auth_ticket_info info = {};

    if (end - *p < sizeof(ticket_type) + sizeof(version)) {
        goto out;
    }

    ceph_decode_copy(p, &ticket_type, sizeof(ticket_type));
    ceph_decode_copy(p, &version, sizeof(version));

    handler = get_ticket_handler(ac, ticket_type);
    if (!handler) {
        goto out;
    }

    if (end - *p < sizeof(ticket_len)) {
        goto out;
    }

    ceph_decode_copy(p, &ticket_len, sizeof(ticket_len));

    if (end - *p < ticket_len) {
        goto out;
    }

    ticket_data = kmalloc(ticket_len, GFP_KERNEL);
    if (!ticket_data) {
        goto out;
    }

    ceph_decode_copy(p, ticket_data, ticket_len);

    if (secret) {
        ret = decrypt_ticket(ticket_data, ticket_len, secret, &new_key, &info);
        if (ret < 0) {
            goto out_free;
        }
    } else {
        ret = -EACCES;
        goto out_free;
    }

    handler->update_session_key(handler, &new_key);
    handler->update_ticket_info(handler, &info);

    ret = 0;

out_free:
    kfree(ticket_data);
out:
    return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac,
                                    struct ceph_crypto_key *secret,
                                    void **p, void *end)
{
  int ret = -EINVAL;
  void *ticket_start = *p;
  int type, version;

  if (*p + sizeof(type) > end)
    goto out;

  type = le32_to_cpu(*(__u32 *)(*p));
  (*p) += sizeof(type);

  if (*p + sizeof(version) > end)
    goto out;

  version = le32_to_cpu(*(__u32 *)(*p));
  (*p) += sizeof(version);

  struct ceph_auth_handshake *h = ac->handshake;
  struct ceph_auth_ticket_handler *handler = ceph_get_ticket_handler(type);
  if (!handler)
    goto out;

  void *decrypted = NULL;
  size_t decrypted_len = 0;
  if (h->has_encrypted) {
    struct ceph_crypto_key *session_key = &h->session_key;
    decrypted = ceph_decrypt_ticket_data(secret, session_key, *p, end - *p, &decrypted_len);
    if (!decrypted)
      goto out;
    *p = decrypted;
  }

  struct ceph_crypto_key new_key;
  memset(&new_key, 0, sizeof(new_key));
  if (ceph_decode_key(*p, end, &new_key)) {
    ret = -EINVAL;
    goto out_key;
  }

  __s64 epoch_sec, epoch_nsec;
  if (*p + sizeof(epoch_sec) + sizeof(epoch_nsec) > end)
    goto out_key;

  epoch_sec = le64_to_cpu(*(__s64 *)(*p));
  (*p) += sizeof(epoch_sec);
  epoch_nsec = le64_to_cpu(*(__s64 *)(*p));
  (*p) += sizeof(epoch_nsec);

  void *blob_start = *p;
  size_t blob_len = end - *p;
  if (blob_len > 0) {
    handler->ticket_blob = kmalloc(blob_len, GFP_NOFS);
    if (!handler->ticket_blob) {
      ret = -ENOMEM;
      goto out_key;
    }
    memcpy(handler->ticket_blob, blob_start, blob_len);
    handler->ticket_blob_len = blob_len;
  }

  ret = ceph_update_session_key(ac, &new_key);
  if (ret < 0)
    goto out_key;

  ret = 0;

out_key:
  ceph_crypto_key_destroy(&new_key);
  if (decrypted)
    kfree(decrypted);
out:
  return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void **p, void *end) {
    int ret = -EINVAL;
    void *ticket_type = *p;
    void *version = ticket_type + sizeof(int);
    int ticket_len = 0;

    if (*p + sizeof(int) + sizeof(int) > end) {
        goto out;
    }

    // Retrieve ticket type and version
    int ticket_type_id = *(int *)ticket_type;
    int version_num = *(int *)version;

    // Retrieve ticket handler
    struct ceph_auth_ticket_handler *handler = get_ticket_handler(ac, ticket_type_id);
    if (!handler) {
        goto out;
    }

    // Move the pointer to the ticket data
    *p = version + sizeof(int);

    // Determine ticket length
    if (*p + sizeof(int) > end) {
        goto out;
    }
    ticket_len = *(int *)*p;
    *p += sizeof(int);

    // Ensure there's enough data left
    if (*p + ticket_len > end) {
        goto out;
    }

    // Allocate memory for the ticket data
    void *ticket_data = kmalloc(ticket_len, GFP_NOFS);
    if (!ticket_data) {
        goto out;
    }

    memcpy(ticket_data, *p, ticket_len);
    *p += ticket_len;

    // Decrypt the ticket data if needed
    if (secret) {
        ret = decrypt_ticket(secret, ticket_data, ticket_len);
        if (ret < 0) {
            goto out_free;
        }
    }

    // Extract session key, validity period, and ticket blob
    void *key = ticket_data;
    void *valid_from = key + sizeof(int);
    void *valid_until = valid_from + sizeof(__s64);
    void *blob = valid_until + sizeof(__s64);

    if (blob + handler->blob_len > ticket_data + ticket_len) {
        ret = -EINVAL;
        goto out_free;
    }

    // Update the session key in the auth client
    ret = update_session_key(ac, key, sizeof(int));
    if (ret < 0) {
        goto out_free;
    }

    // Update the ticket information in the handler
    handler->valid_from = *(int *)valid_from;
    handler->valid_until = *(int *)valid_until;
    memcpy(handler->ticket_blob, blob, handler->blob_len);

    ret = 0;

out_free:
    kfree(ticket_data);
out:
    return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void **p, void *end) {
    int err = 0;
    struct ceph_auth_ticket *ticket;
    struct ceph_auth_handler *handler;
    void *ticket_data;
    int ticket_len;
    int encrypted;

    ceph_decode_need(p, end, sizeof(*ticket), "ticket");
    ticket = ceph_decode_copy(p, sizeof(*ticket));
    if (!ticket) {
        return -ENOMEM;
    }

    handler = ceph_get_auth_handler(ac, ticket->type);
    if (!handler) {
        err = -EINVAL;
        goto out;
    }

    ticket_data = ceph_decode_start(p, end, &ticket_len, "ticket data");
    if (!ticket_data) {
        err = -ENOMEM;
        goto out;
    }

    encrypted = ceph_test_bit(ticket->flags, CEPH_AUTH_TICKET_ENCRYPTED);

    if (encrypted) {
        err = ceph_decrypt_data(secret, ticket_data, ticket_len, &ticket_data, &ticket_len);
        if (err < 0) {
            goto out;
        }
    }

    err = handler->decode_ticket(ac, ticket_data, ticket_len);
    if (err < 0) {
        goto out;
    }

    err = 0;

out:
    kfree(ticket);
    return err;
}

int process_ticket(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void **p, void *end) {
    int ret = 0;
    uint32_t ticket_type;
    uint32_t version;
    struct ceph_auth_ticket_handler *handler;

    // Decode ticket type and version
    if ((ret = ceph_decode_u32(&ticket_type, p, end)) < 0)
        goto out;

    if ((ret = ceph_decode_u32(&version, p, end)) < 0)
        goto out;

    // Retrieve appropriate ticket handler
    handler = ceph_get_ticket_handler(ac, ticket_type);
    if (!handler) {
        ret = -EINVAL;
        goto out;
    }

    // Decrypt ticket data
    if ((ret = ceph_decrypt_ticket(&p, end, secret, handler->encrypted)) < 0)
        goto out;

    // Extract new session key
    if ((ret = ceph_decode_crypto_key(&handler->session_key, p, end)) < 0)
        goto out;

    // Extract validity period
    if ((ret = ceph_decode_u64(&handler->valid_until, p, end)) < 0)
        goto out;

    // Extract ticket blob
    if ((ret = ceph_decode_blob(&handler->ticket_blob, p, end)) < 0)
        goto out;

    // Update session key and ticket info in the handler
    ceph_update_session_key(ac, &handler->session_key);
    ceph_update_ticket_info(handler);

out:
    // Clean up allocated resources
    if (ret < 0)
        ceph_cleanup_ticket_resources(handler);

    return ret;
}
